SELECT StromAus2.Elektrolyseur, StromAus2.Datum, StromAus2.Zeit, StromAusVAno.VAnolyt, ([StromAus2]![NaClO3 An]*[StromAusVAno]![VAnolyt]-[StromAus2]![NaClO3 Pb]*[StromAus2]![flow rate])*100/([UnElekFV]![I Gesamt]*[UnElekFV]![Elementzahl]*3*0.662) AS µNaClO3, ([StromAus2]![NaOCl An]*[StromAusVAno]![VAnolyt]*100)/([UnElekFV]![I Gesamt]*[UnElekFV]![Elementzahl]*3*1.38869) AS µNaOCl, ([StromAus2]![NaOH Pb]*[StromAus2]![flow rate]*100)/([UnElekFV]![I Gesamt]*[UnElekFV]![Elementzahl]*3*1.4923) AS µAlkali, ([StromAus2]![Na2CO3 Pb]*[StromAus2]![flow rate]*100)/([UnElekFV]![I Gesamt]*[UnElekFV]![Elementzahl]*3*1.978) AS µNa2CO3, (2*[Analyse Chlorgas]![O2 Cl]/([Analyse Chlorgas]![Cl2 + CO2 Cl]+2*[Analyse Chlorgas]![O2 Cl]))*(100-[µNaClO3]-[µNaOCl]) AS µO2, 100-[µO2]-[µNaClO3]-[µNaOCl]+[µNa2CO3]+[µAlkali] AS µNaOH
FROM ((StromAus2 INNER JOIN StromAusVAno ON (StromAus2.Datum = StromAusVAno.Datum) AND (StromAus2.Elektrolyseur = StromAusVAno.Elektrolyseur)) INNER JOIN UnElekFV ON (StromAus2.Datum = UnElekFV.Datum) AND (StromAus2.Elektrolyseur = UnElekFV.Elektrolyseur)) INNER JOIN [Analyse Chlorgas] ON (StromAus2.Datum = [Analyse Chlorgas].Datum) AND (StromAus2.Elektrolyseur = [Analyse Chlorgas].Elektrolyseur)
ORDER BY StromAus2.Elektrolyseur, StromAus2.Datum;
